const path = require('node:path');

const docsRoot = path.resolve(__dirname, '..', 'docs');

// Hide a folder's own index page from its autogenerated items; the category links to it instead.
async function sidebarItemsGenerator({ defaultSidebarItemsGenerator, ...args }) {
  const items = await defaultSidebarItemsGenerator(args);
  const indexId = `${args.item.dirName}/index`;
  return items.filter((item) => !(item.type === 'doc' && item.id === indexId));
}

module.exports = {
  title: 'PV Today - Internal Docs',
  tagline: 'Project planning, work tracking and technical reference',
  url: 'http://localhost:8080',
  baseUrl: '/internal/docs/',
  trailingSlash: true,
  onBrokenLinks: 'warn',
  markdown: {
    format: 'detect',
    mermaid: true,
    hooks: { onBrokenMarkdownLinks: 'warn' },
  },
  themes: ['@docusaurus/theme-mermaid'],
  plugins: [require.resolve('./plugins/work-docs.cjs')],
  presets: [
    [
      'classic',
      {
        docs: {
          path: docsRoot,
          include: [
            'planning/**/*.{md,mdx}',
            'epics/**/*.{md,mdx}',
            'templates/**/*.{md,mdx}',
            'reference/**/*.{md,mdx}',
          ],
          routeBasePath: '/',
          sidebarPath: require.resolve('./sidebars.js'),
          sidebarItemsGenerator,
          breadcrumbs: true,
        },
        blog: false,
        theme: { customCss: require.resolve('./src/css/custom.css') },
      },
    ],
  ],
  themeConfig: {
    navbar: {
      title: 'Internal Docs',
      items: [
        { to: '/work/', label: 'Dashboard', position: 'left' },
        {
          type: 'dropdown',
          label: 'Planning',
          position: 'left',
          items: [
            { type: 'doc', docId: 'planning/workflow', label: 'Workflow' },
            { type: 'doc', docId: 'epics/index', label: 'Epics' },
            { type: 'doc', docId: 'templates/EPIC_TEMPLATE', label: 'Templates' },
          ],
        },
        { type: 'docSidebar', sidebarId: 'reference', label: 'Reference', position: 'left' },
        {
          type: 'html',
          value: '<a class="navbar__link" href="/">Back to app</a>',
          position: 'right',
        },
      ],
    },
    docs: { sidebar: { autoCollapseCategories: true, hideable: true } },
    tableOfContents: { minHeadingLevel: 2, maxHeadingLevel: 3 },
  },
};
